"""Regenerate .gitignore from the ACTUAL public tree (inverse selection).

The whitelist = every file currently in the tree (top-level files + dirs), minus
explicitly excluded patterns (db/logs/pycache). Run after adding new top-level files.
"""
import os

BASE = os.path.dirname(os.path.abspath(__file__))
EXCLUDE_EXT = {".db", ".db-wal", ".db-shm", ".log", ".pyc", ".fsp"}
EXCLUDE_NAMES = {"__pycache__", ".pytest_cache", "data", "backups"}
TOP_EXTRA = ["README.md", "LICENSE", ".gitignore"]


def main():
    lines = [
        "# AUTO-GENERATED by make_gitignore.py — inverse selection:",
        "# ignore everything, whitelist the tracked set below.",
        "# Regenerate after adding new top-level files:  python make_gitignore.py",
        "",
        "/*",
        "",
        "# ---- whitelisted (tracked) ----",
    ]
    seen_dirs = set()
    for dp, dn, fn in os.walk(BASE):
        rel = os.path.relpath(dp, BASE)
        if rel == ".":
            # top-level files
            for f in sorted(fn):
                if os.path.splitext(f)[1] not in EXCLUDE_EXT:
                    lines.append("!/%s" % f)
            # top-level dirs
            for d in sorted(dn):
                if d not in EXCLUDE_NAMES and not d.startswith("."):
                    lines.append("!/%s/" % d)
                    seen_dirs.add(d)
            continue
        # nested files -> whitelist with full path, prune excluded
        dn[:] = [d for d in dn if d not in EXCLUDE_NAMES and not d.startswith(".")]
        for f in sorted(fn):
            if os.path.splitext(f)[1] in EXCLUDE_EXT:
                continue
            relf = os.path.relpath(os.path.join(dp, f), BASE).replace("\\", "/")
            lines.append("!/%s" % relf)

    lines += [
        "",
        "# ---- still ignored inside whitelisted dirs ----",
        "**/__pycache__/",
        "**/*.pyc",
        "**/*.db",
        "**/*.db-wal",
        "**/*.db-shm",
        "**/*.log",
        "**/.DS_Store",
        "shim/data/",
        "compat/backups/",
        "compat/community/",
        "capabilities/snapshots/",
    ]
    out = os.path.join(BASE, ".gitignore")
    open(out, "w", encoding="utf-8", newline="\n").write("\n".join(lines) + "\n")
    print("wrote", out, "with", sum(1 for l in lines if l.startswith("!/")), "whitelist entries")


if __name__ == "__main__":
    main()
